// @ts-nocheck
// ===== Extruder03 : อ่านน้ำหนักจาก PLC Omron NJ 192.168.250.1 ด้วย FINS UDP (ทดสอบแล้วว่า SA1=2 ใช้ได้) =====
// ค่าที่เจอ D554=12336 (0x3030 = "00"), D555=11824 (0x2E30 = ".0") → PLC เก็บน้ำหนักเป็น "ตัวอักษร ASCII" จากเครื่องชั่ง
// จึงอ่านช่วง D540–D579 มาทั้งก้อน แล้วถอดเป็นข้อความ หาเลขน้ำหนักในนั้น
// NJ เก็บ STRING แบบ byte ต่ำก่อน -> ต้องสลับ byte ในแต่ละ word ("TS+," -> "ST,+")
// รูปแบบเครื่องชั่ง: "ST,+0000.000 g"  ST=นิ่ง US=ยังไม่นิ่ง OL=เกินพิกัด
const HOST = "192.168.250.1", DA1 = 1, SA1 = 2;
const START = 540, COUNT = 40;          // ช่วงที่อ่าน (ดู dump แล้วค่อยแคบลงได้)
const W_FROM = 550, W_TO = 565;         // ช่วงที่ใช้หาเลขน้ำหนัก (word)
const SWAP = true;                      // สลับ byte (NJ = true)
const RETRY = 2;                        // ลองซ้ำเมื่อ timeout (สายมี packet หาย)
const ERR_AFTER = 5;                    // timeout ติดกันกี่ครั้งถึงแจ้ง error

function wordStr(w) { let a = (w >> 8) & 0xFF, b = w & 0xFF; if (SWAP) { const t = a; a = b; b = t; } return [a, b].map(c => c >= 32 && c < 127 ? String.fromCharCode(c) : "·").join(""); }

if (context.get("busy")) return null;
context.set("busy", true);
const sid = ((context.get("sid") || 0) + 1) & 0xFF; context.set("sid", sid);
const req = Buffer.from([0x80, 0, 0x02, 0, DA1, 0, 0, SA1, 0, sid,
    0x01, 0x01, 0x82, (START >> 8) & 0xFF, START & 0xFF, 0, (COUNT >> 8) & 0xFF, COUNT & 0xFF]);
function attempt(left) {
const s = dgram.createSocket("udp4"); let done = false;
const finish = (err, r) => {
    if (done) return; done = true; try { s.close(); } catch (e) {}
    if (err && left > 0) return attempt(left - 1);
    context.set("busy", false);
    if (err) {
        const n = (context.get("fail") || 0) + 1; context.set("fail", n);
        if (n >= ERR_AFTER) node.status({ fill: "red", shape: "ring", text: err + " ติดกัน " + n + " ครั้ง" });
        if (n === ERR_AFTER || (n > ERR_AFTER && n % 60 === 0)) node.send([null, null, { payload: { error: err + " ติดกัน " + n + " ครั้ง (เช็คสาย LAN / PLC)" } }]);
        return;
    }
    context.set("fail", 0);
    const ec = r.readUInt16BE(12);
    if (ec !== 0 && ec !== 0x0040) { node.status({ fill: "red", shape: "dot", text: "end code 0x" + ec.toString(16) }); node.send([null, null, { payload: { error: "PLC end code 0x" + ec.toString(16) } }]); return; }
    const w = []; for (let k = 0; k < COUNT; k++) w.push(r.readUInt16BE(14 + k * 2));
    const at = d => w[d - START];
    // ข้อความ ASCII ของช่วงน้ำหนัก
    let txt = ""; for (let d = W_FROM; d <= W_TO; d++) txt += wordStr(at(d));
    txt = txt.replace(/·/g, " ").replace(/\s+/g, " ").trim();
    // "ST,+0000.000 g" -> สถานะ, เครื่องหมาย, ตัวเลข, หน่วย (เอาชุดแรก)
    const mm = txt.match(/([A-Z]{2})?\s*,?\s*([+-])?\s*(\d+(?:\.\d+)?)\s*([a-z]{1,3})?/);
    const weight = mm ? parseFloat((mm[2] === "-" ? "-" : "") + mm[3]) : null;
    const UNIT = (mm && mm[4]) || "";
    const stat = mm && mm[1] ? ({ ST: "นิ่ง", US: "ยังไม่นิ่ง", OL: "เกินพิกัด", QT: "นับชิ้น" }[mm[1]] || mm[1]) : "";
    flow.set("ex03_weight", { weight, unit: UNIT, stable: mm && mm[1] === "ST", text: txt, ts: Date.now() });
    node.status({ fill: weight === null ? "yellow" : mm[1] === "ST" ? "green" : "yellow", shape: "dot", text: (weight === null ? "ไม่พบตัวเลข" : weight + " " + UNIT + (stat ? " · " + stat : "")) });
    const dump = {};
    for (let d = START; d < START + COUNT; d++) { const v = at(d); dump["D" + d] = v + " | 0x" + v.toString(16).padStart(4, "0") + " | \"" + wordStr(v) + "\""; }
    let all = ""; for (let d = START; d < START + COUNT; d++) all += wordStr(at(d));
    node.send([
        { payload: { machine: "Extruder03", weight, unit: UNIT, stable: !!(mm && mm[1] === "ST"), สถานะ: stat, ข้อความจากเครื่องชั่ง: txt, time: new Date().toLocaleTimeString("th-TH") } },
        { payload: { ["ข้อความ D" + START + "-D" + (START + COUNT - 1)]: all, ...dump } },
        null
    ]);
};
s.on("error", e => finish("socket " + e.code));
s.on("message", r => { if (r.length >= 14 && r[9] === sid) finish(null, r); });
s.bind(0, () => {
    s.send(req, 9600, HOST, e => { if (e) finish("send " + e.code); });
    setTimeout(() => finish("timeout"), 700);
});
}
attempt(RETRY);
return null;

// @ts-nocheck
// ===== ส่งน้ำหนักขึ้น Server เฉพาะ "ชั่งเสร็จ 1 ครั้ง" =====
// - น้ำหนัก ไม่เกิน 1.0 g : ไม่ส่ง (รอวางของ / ค่าแกว่ง)
// - วางของแล้ว + นิ่ง (ST) + ค่าเดิมติดกัน NEED_SAME รอบ -> ส่ง 1 ครั้ง
// - ยังวางค้างอยู่ -> ไม่ส่งซ้ำ จนกว่าจะยกออก (กลับเป็น 0) แล้ววางชิ้นใหม่
// - ส่งไม่สำเร็จ -> เก็บคิวไว้ ส่งใหม่รอบถัดไป (ไม่หาย)
const MACHINE     = "Extruder03";
const MIN_G       = 1.0;   // ส่งเมื่อน้ำหนัก > 1.0 g เท่านั้น (หน่วย kg จะแปลงเป็นกรัมก่อนเทียบ)
const NEED_SAME   = 2;     // ค่าเดิมติดกันกี่รอบถึงนับว่านิ่ง (รอบละ 2 วินาที)
const RESEND_DIFF = 0;     // วางค้างแต่น้ำหนักเปลี่ยนเกินค่านี้ -> ส่งใหม่ (0 = ไม่ส่ง)

// ส่งของที่ค้างในคิวก่อน (ครั้งละ 1)
const q = flow.get("ex03_queue") || [];
if (q.length) { const item = q.shift(); flow.set("ex03_queue", q); node.send({ payload: item, queued: true }); }

const p = msg.payload || {}, w = p.weight;
if (w === null || w === undefined || isNaN(w)) return null;

const grams = String(p.unit || "").toLowerCase() === "kg" ? w * 1000 : w;
if (grams <= MIN_G) {
    context.set("armed", true); context.set("same", 0); context.set("last", null);
    node.status({ fill: "grey", shape: "ring", text: "รอวางของ · ส่งแล้ว " + (context.get("count") || 0) + " ครั้ง" + (q.length ? " · ค้างคิว " + q.length : "") });
    return null;
}
const same = context.get("last") === w ? (context.get("same") || 0) + 1 : 1;
context.set("same", same); context.set("last", w);
if (!p.stable || same < NEED_SAME) { node.status({ fill: "yellow", shape: "ring", text: "รอนิ่ง " + w + " " + (p.unit || "") }); return null; }

const armed = context.get("armed") !== false, sentW = context.get("sentW");
if (armed || (RESEND_DIFF > 0 && sentW != null && Math.abs(w - sentW) >= RESEND_DIFF)) {
    context.set("armed", false); context.set("sentW", w);
    const n = (context.get("count") || 0) + 1; context.set("count", n);
    node.status({ fill: "green", shape: "dot", text: "ส่ง " + w + " " + (p.unit || "") + " · ครั้งที่ " + n });
    return { payload: { machine: MACHINE, weight: w, unit: p.unit || "", stable: true, text: p["ข้อความจากเครื่องชั่ง"] || "" } };
}
node.status({ fill: "blue", shape: "dot", text: "ส่งแล้ว " + sentW + " · รอยกของออก" });
return null;

// server ตอบไม่ใช่ 200 -> เข้าคิวเหมือน error
if (msg.statusCode !== 200) {
    const q = flow.get("ex03_queue") || [];
    const body = msg.sent || null;
    if (body && q.length < 500) { q.push(body); flow.set("ex03_queue", q); }
    node.status({ fill: "red", shape: "ring", text: "HTTP " + msg.statusCode + " · ค้างคิว " + q.length });
} else node.status({ fill: "green", shape: "dot", text: "บันทึกแล้ว " + new Date().toLocaleTimeString("th-TH") });
return msg;

// ส่งไม่สำเร็จ -> เก็บเข้าคิว (สูงสุด 500 รายการ) ให้ node ส่งค่าลองใหม่
const q = flow.get("ex03_queue") || [];
if (msg.sent && msg.sent.weight > 0 && q.length < 500) q.push(msg.sent);
flow.set("ex03_queue", q);
node.status({ fill: "red", shape: "ring", text: "ส่งไม่ได้ · ค้างคิว " + q.length });
return { payload: { error: msg.error && msg.error.message, ค้างคิว: q.length } };
